 void LoadValues(){string path=System.IO.Path.Combine(AppPaths.Data,"desktop.ini");if(File.Exists(path))foreach(string line in File.ReadAllLines(path)){int i=line.IndexOf('=');if(i<1)continue;string k=line.Substring(0,i),v=line.Substring(i+1).Trim();if(k=="allow" || k=="exclude"){if(!rules.Any(r=>string.Equals(r.Path,v,StringComparison.OrdinalIgnoreCase)))rules.Add(MakeRule(v,k=="exclude"));}else values[k]=v;}
  Get<Slider>("Speed").Value=ReadNumber("speed",0.02)/0.02;Get<Slider>("Smooth").Value=ReadNumber("smoothMs",12);Get<Slider>("Friction").Value=ReadNumber("friction",8);
  string[] controls={"Inertia","Global"},keys={"inertia","global"};for(int i=0;i<keys.Length;i++){string v;Get<CheckBox>(controls[i]).IsChecked=values.TryGetValue(keys[i],out v)?string.Equals(v,"true",StringComparison.OrdinalIgnoreCase):i<2;}}
 double ReadNumber(string k,double fallback){string s;double n;return values.TryGetValue(k,out s) && double.TryParse(s,NumberStyles.Float,CultureInfo.InvariantCulture,out n) && !double.IsInfinity(n) && !double.IsNaN(n)?n:fallback;}
 string Settings(){values["speed"]=(Get<Slider>("Speed").Value*0.02).ToString(CultureInfo.InvariantCulture);values["smoothMs"]=Get<Slider>("Smooth").Value.ToString(CultureInfo.InvariantCulture);values["friction"]=Get<Slider>("Friction").Value.ToString(CultureInfo.InvariantCulture);string[] controls={"Inertia","Global"},keys={"inertia","global"};for(int i=0;i<keys.Length;i++)values[keys[i]]=(Get<CheckBox>(controls[i]).IsChecked==true).ToString();// The old backend calls this flag SteamDesktopMuted; in this UI it is an explicit warning-only conflict policy, not a claim that Steam was inspected or changed.
values["devicePath"]=selectedDevicePath;values["steamDesktopMuted"]="True";values["leftScroll"]="True";values["pressureClick"]="True";values["padProfiles"]=PadPath;values["rightHaptics"]="False";values["motionHaptics"]="False";var b=new StringBuilder();foreach(var kv in values)b.AppendLine(kv.Key+"="+kv.Value);foreach(var r in rules)b.AppendLine((r.Excluded?"exclude=":"allow=")+r.Path);return b.ToString();}
