 static Rule MakeRule(string path,bool exclude){var rule=new Rule{Path=path,Excluded=exclude};try{using(var icon=System.Drawing.Icon.ExtractAssociatedIcon(path)){if(icon!=null){var img=Imaging.CreateBitmapSourceFromHIcon(icon.Handle,Int32Rect.Empty,BitmapSizeOptions.FromWidthAndHeight(32,32));img.Freeze();rule.AppIcon=img;}}}catch{}return rule;}
 static string ResolvePath(string path){if(path.IndexOfAny(new[]{'\r','\n','"'})>=0)throw new Exception(L.T("无效的应用路径。"));path=System.IO.Path.GetFullPath(path);if(System.IO.Path.GetExtension(path).Equals(".lnk",StringComparison.OrdinalIgnoreCase)){object shell=null,shortcut=null;try{var type=Type.GetTypeFromProgID("WScript.Shell");shell=Activator.CreateInstance(type);shortcut=type.InvokeMember("CreateShortcut",System.Reflection.BindingFlags.InvokeMethod,null,shell,new object[]{path});path=Convert.ToString(shortcut.GetType().InvokeMember("TargetPath",System.Reflection.BindingFlags.GetProperty,null,shortcut,null));}finally{if(shortcut!=null)Marshal.FinalReleaseComObject(shortcut);if(shell!=null)Marshal.FinalReleaseComObject(shell);}}
