 void AddPaths(IEnumerable<string> paths,bool exclude){int added=0;var errors=new List<string>();foreach(string raw in paths)try{string p=ResolvePath(raw);if(Directory.Exists(p) && !exclude)throw new Exception(L.T("文件夹只能用于整组排除，请选择具体程序以接管。"));string name=System.IO.Path.GetFileName(p);if(!exclude && new[]{"gameoverlayui.exe"}.Contains(name,StringComparer.OrdinalIgnoreCase))throw new Exception(L.T("Steam 游戏覆盖层由 Steam 管理。"));var old=rules.FirstOrDefault(r=>string.Equals(r.Path,p,StringComparison.OrdinalIgnoreCase));if(old!=null)old.Excluded=exclude;else rules.Add(MakeRule(p,exclude));added++;}catch(Exception e){errors.Add(System.IO.Path.GetFileName(raw)+"："+e.Message);}RefreshRules();Notice(L.T("已添加或更新 ")+added+L.T(" 条规则，保存后生效。")+(errors.Count>0?L.T(" 有 ")+errors.Count+L.T(" 项未导入。"):""));if(errors.Count>0)MessageBox.Show(window,string.Join("\n",errors.ToArray()),L.T("未导入的项目"));}
