 void ImportHaptic(){var d=new Microsoft.Win32.OpenFileDialog{Title=L.T("导入录制工具保存的配置"),Filter=L.T("触觉配置|*.json")};if(d.ShowDialog(window)!=true)return;Guard(delegate{string text=File.ReadAllText(d.FileName);if(text.Length>65536)throw new Exception(L.T("配置文件过大。"));var obj=new JavaScriptSerializer().DeserializeObject(text) as Dictionary<string,object>;if(obj==null || !obj.ContainsKey("motion") || !obj.ContainsKey("click"))throw new Exception(L.T("请选择录制工具导出的“当前触觉配置.json”。"));Directory.CreateDirectory(System.IO.Path.Combine(AppPaths.Data,"profiles"));AtomicWrite(System.IO.Path.Combine(AppPaths.Data,"profiles","haptics.json"),text);ShowHaptic();Notice(L.T("已导入用于保存和查看；尚未应用到桌面输出。"));});}
 void ShowHaptic(){string p=System.IO.Path.Combine(AppPaths.Data,"profiles","haptics.json");if(!File.Exists(p))return;try{var d=new JavaScriptSerializer().DeserializeObject(File.ReadAllText(p)) as Dictionary<string,object>;var m=d["motion"] as Dictionary<string,object>;var c=d["click"] as Dictionary<string,object>;Get<TextBlock>("HapticSummary").Text=L.T("滑动 · ")+Convert.ToString(m["description"])+L.T("\n点击 · ")+Convert.ToString(c["description"]);}catch{Get<TextBlock>("HapticSummary").Text=L.T("配置无法读取，请重新导入。");}}
 static void SelfTest(){UpdateRelease.Test();var now=DateTimeOffset.UtcNow;if(!SigningDue(now.AddDays(30),now) || SigningDue(now.AddDays(31),now) || !SigningDue(now.AddDays(-1),now))throw new Exception("Signing reminder boundary");TestShare();TestStarterPresets();TestFineWheel();PadBook.Test();string windows=Environment.GetFolderPath(Environment.SpecialFolder.Windows);string p=System.IO.Path.Combine(windows,"explorer.exe");if(ResolvePath(p)!=p)throw new Exception("EXE import");bool bad=false;try{ResolvePath(System.IO.Path.Combine(Root,"source","Main.xaml"));}catch{bad=true;}if(!bad)throw new Exception("Non executable accepted");var app=new Application();var ui=new PadHop(false);ui.testing=true;ui.TestScrollEditor();ui.TestBindingDialogs();ui.TestStickEditor();ui.padBook=new PadBook();ui.LoadPad();string ini=ui.Settings();if(!ini.Contains("leftScroll=True") || !ini.Contains("pressureClick=True") || !ini.Contains("steamDesktopMuted=True"))throw new Exception("Unified input / warning-only policy");if(!ini.Contains("rightHaptics=False") || !ini.Contains("motionHaptics=False"))throw new Exception("Legacy haptics must remain disabled");ui.CurrentPad.Motion.OnUs=650;ui.LoadWave();ui.numberSliders[ui.waveFields[0]].Value=700;ui.ReadEditor();if(ui.padBook.Left.Motion.OnUs!=700 || ui.padBook.Right.Motion.OnUs!=400)throw new Exception("Wave editor is disconnected or coupled");ui.padTabs.SelectedIndex=1;if(ui.numberSliders[ui.waveFields[0]].Value!=400 || ui.waveFields[0].Text!="400")throw new Exception("Switching target lost independent parameters");ui.TestPresets();ui.editedSide=0;ui.TestRecordingMerge();ui.SetBinding("L5",new BindingAction());if(Clone(ui.padBook).EffectiveBindings()["L5"].Kind!="none")throw new Exception("Unbind failed");ui.SetBinding("L4",new BindingAction{Kind="keyboard",Chord="Win+D"});if(Clone(ui.padBook).EffectiveBindings()["L4"].Chord!="Win+D")throw new Exception("Shortcut persistence");ui.padTabs.SelectedIndex=0;ui.actionBox.SelectedIndex=2;ui.SetBinding("LP_UP",new BindingAction{Kind="keyboard",Chord="W"});ui.SetBinding("LPRESS",new BindingAction{Kind="gamepad",Chord="A"});ui.deadzoneField.Text="30";ui.ReadEditor();var mapped=Clone(ui.padBook);if(mapped.Left.Action!="directions" || mapped.Left.Deadzone!=30 || mapped.EffectiveBindings()["LP_UP"].Chord!="W" || mapped.EffectiveBindings()["LPRESS"].Chord!="A" || !mapped.NeedsVirtualGamepad)throw new Exception("Pad mapping UI persistence");ui.padTabs.SelectedIndex=1;if(ui.CurrentPad.Action=="directions")throw new Exception("Pad mapping leaked across sides");ui.TestAppProfiles();ui.rules.Add(new Rule{Path=p,Excluded=false});ui.rules.Add(new Rule{Path=windows,Excluded=true});ui.Navigate("Rules");ui.Get<TabControl>("RuleTabs").SelectedIndex=1;ui.RefreshRules();foreach(Rule r in ui.Get<ListBox>("RuleList").Items)if(!r.Excluded)throw new Exception("Mixed rule tabs");ui.Get<TabControl>("RuleTabs").SelectedIndex=0;ui.RefreshRules();foreach(Rule r in ui.Get<ListBox>("RuleList").Items)if(r.Excluded)throw new Exception("Mixed rule tabs");if(ui.Get<StackPanel>("RulesPage").Visibility!=Visibility.Visible)throw new Exception("Navigation");File.WriteAllText(System.IO.Path.Combine(AppPaths.Data,"self-test.txt"),"PASS: XAML, rule tabs, EXE validation, shared wave editing, independent left/right switching, unified input settings.");app.Shutdown();}
 string EngineError(){if(log!=null && File.Exists(log)){var lines=File.ReadAllLines(log);for(int i=lines.Length-1;i>=0;i--)if(lines[i].Contains("ERROR") || lines[i].Contains("HELPER STOPPED"))return lines[i];}return L.T("请查看 logs 中本次试用日志。");}
